<script setup lang="ts">import {ref,onMounted,watch,computed} from 'vue';import {useResearch} from '../stores/research';import {useDays} from '../stores/days';import {useAuth} from '../stores/auth';import {createDataset} from '../api/datasets';import {useTask} from '../hooks/useTask';import {number} from '../utils/format';import {features,shortNames} from '../constants/enums';import type {Day} from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import DatasetSelect from '../components/DatasetSelect.vue';import EmptyState from '../components/common/EmptyState.vue';const lab=useResearch(),days=useDays(),auth=useAuth(),selected=ref(0),building=ref(''),offset=ref(0),show=ref(false),name=ref(''),source=ref('ls-energy-days.csv'),csv=ref('building_code,day,temperature_c,operating_hours,area_m2,visitors,humidity_pct,equipment_kw,holiday_flag,energy_kwh\n'),{busy,error,perform}=useTask();const dataset=computed(()=>lab.datasets.find(d=>d.id===selected.value)),buildings=computed(()=>[...(dataset.value?.train_buildings||[]),...(dataset.value?.test_buildings||[])].sort()),featureKeys=Object.keys(features),scope=computed(()=>days.missing?.scope),imputed=computed(()=>days.imputation?.imputation);const featureValue=(d:Day,key:string):number|undefined=>{const value=d[key as keyof Day];return typeof value==='number'?value:undefined;};async function load(){if(selected.value)await days.load(selected.value,building.value,offset.value);}onMounted(()=>perform(async()=>{await lab.load();selected.value=lab.datasets[0]?.id||0;await load();}));watch(selected,()=>{offset.value=0;building.value='';perform(load);});watch(building,()=>{offset.value=0;perform(load);});function submit(){perform(async()=>{const result=await createDataset({name:name.value,source_file:source.value,csv_text:csv.value,note:'团队导入的机构级楼宇日能耗记录'});await lab.load();selected.value=result.id;show.value=false;});}</script><template><PageHeading index="02" title="把同一栋楼，留在同一侧" text="训练与封存按楼宇分开；缺测特征保留原始空缺，按训练阶段中位数补值。"><button v-if="auth.canEdit" class="outline" @click="show=!show">{{show?'收起导入':'导入新楼宇数据 +'}}</button></PageHeading><ErrorNotice :message="error" @retry="perform(load)"/><form v-if="show" class="entry-form" @submit.prevent="submit"><h2>导入尚未评估的新楼宇研究数据</h2><div class="form-grid"><label>数据集名称<input v-model="name" required minlength="2"></label><label>来源文件<input v-model="source" required></label></div><label>CSV内容<textarea v-model="csv" rows="7" required></textarea></label><p class="input-note">8栋及以上、每栋至少6天，48–5000行；同一楼宇同一天唯一。特征单元格可留空表示缺测，会保留并在建模时按训练行中位数补齐；能耗目标不能留空。新方案应使用新采集的未见楼宇，不用重导旧数据规避封存。</p><button class="primary" :disabled="busy">校验并建立数据集 →</button></form><div class="data-toolbar"><DatasetSelect v-model="selected" :datasets="lab.datasets"/><label>观察楼宇<select v-model="building"><option value="">全部楼宇</option><option v-for="code in buildings" :key="code" :value="code">{{code}} / {{dataset?.test_buildings.includes(code)?'封存':'训练'}}</option></select></label></div><div class="source-caption"><b>{{dataset?.source_file}}</b><span>{{dataset?.row_count}}行 / {{dataset?.building_count}}栋</span><span>缺测 {{dataset?.missing_rows??0}}行 / {{dataset?.missing_cells??0}}格</span><p>{{dataset?.note}}</p></div><p class="sealed-notice">{{dataset?.evaluation_released?'封存评估已公开；原始能耗可见，选模配置保持锁定。':'封存楼宇的目标能耗暂不显示，首次方案锁定并完成选模后才公开最终评估。'}}</p><section v-if="scope" class="missing-panel"><div class="section-heading"><h2>特征缺测与补值依据</h2><span>{{imputed?'补值来自最近一次完成的训练':'首次锁定训练后记录补值'}}</span></div><div class="table-wrap"><table><thead><tr><th>分组</th><th>记录</th><th>含缺测行 / 缺测格</th><th v-for="key in featureKeys" :key="key">{{shortNames[key]}}</th></tr></thead><tbody><tr v-for="label in (['train','sealed'] as const)" :key="label"><td><b>{{label==='train'?'训练楼宇':'封存楼宇'}}</b></td><td>{{scope[label].rows}}行 / {{Object.keys(scope[label].buildings).length}}栋</td><td>{{scope[label].rows_with_missing}}行 / {{scope[label].cells}}格</td><td v-for="key in featureKeys" :key="key">{{scope[label].by_feature[key]}}</td></tr></tbody></table></div><div class="table-wrap"><table><thead><tr><th>特征</th><th>训练缺测行</th><th>最终模型补值 / 训练中位数</th><th>各折补值</th><th>折内回退</th></tr></thead><tbody><tr v-for="key in featureKeys" :key="key"><td>{{shortNames[key]}}</td><td>{{imputed?.train_missing?.[key]??'—'}}</td><td>{{imputed?number(imputed.features[key],4):'待训练'}}</td><td>{{days.imputation?.folds?.map(f=>number(f.impute_values[key],4)).join(' / ')||'—'}}</td><td>{{days.imputation?.folds?.map(f=>f.impute_fallback.includes(key)?'是':'—').join(' / ')||'—'}}</td></tr></tbody></table></div><details v-if="imputed"><summary>补值口径与复算记录</summary><p class="input-note">{{imputed.fit_scope}} 共{{imputed.training_rows}}条训练行参与计算；封存特征的缺测情况不改变补值、候选成绩或胜出配置，只影响最终评估。</p><pre>{{JSON.stringify(imputed,null,2)}}</pre></details><p v-else class="input-note">尚未完成模型训练：缺测已保留在原始记录中，提交研究后按该阶段训练行中位数补齐并在此展示。</p></section><div class="table-wrap"><table><thead><tr><th>楼宇 / 日期</th><th>分组</th><th v-for="key in featureKeys" :key="key">{{shortNames[key]}}</th><th>能耗 kWh</th></tr></thead><tbody><tr v-for="d in days.rows" :key="d.id" :class="{sealed:d.sealed}"><td><b>{{d.building_code}}</b><small>{{d.day}}</small></td><td>{{d.sealed?'封存':'训练'}}</td><td v-for="key in featureKeys" :key="key" :class="{missing:d.missing_features.includes(key)}">{{number(featureValue(d,key),key==='visitors'?0:2)}}<small v-if="d.missing_features.includes(key)">缺测</small></td><td>{{d.energy_kwh===null?'封存目标':number(d.energy_kwh,2)}}</td></tr></tbody></table></div><EmptyState v-if="!days.rows.length&&!busy" title="尚无匹配记录" text="选择一个楼宇数据集，或先导入有完整表头的CSV。"/><div class="pagination"><span>共{{days.total}}行 / {{offset+1}}—{{Math.min(offset+20,days.total)}}</span><div><button :disabled="offset===0" @click="offset-=20;perform(load)">← 前20行</button><button :disabled="offset+20>=days.total" @click="offset+=20;perform(load)">后20行 →</button></div></div></template>
